//! Typed IDs. Every ID is a UUID v7, generated by the caller: the domain has no clock and
//! no randomness. Wrappers keep a bare `Uuid` out of every signature.

use std::fmt;

use uuid::Uuid;

/// Why a value is not a valid ID.
#[derive(Debug, Clone, Copy, PartialEq, Eq, thiserror::Error)]
pub enum IdError {
    #[error("not a UUID")]
    Malformed,
    #[error("not a UUID v7")]
    NotV7,
}

macro_rules! uuid_v7_id {
    ($(#[$doc:meta])* $name:ident) => {
        $(#[$doc])*
        #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
        pub struct $name(Uuid);

        impl $name {
            /// Wraps `uuid` if it is a version 7 UUID.
            pub fn from_uuid(uuid: Uuid) -> Result<Self, IdError> {
                if uuid.get_version_num() == 7 {
                    Ok(Self(uuid))
                } else {
                    Err(IdError::NotV7)
                }
            }

            /// Parses the text form (any case, surrounding whitespace ignored).
            pub fn parse(raw: &str) -> Result<Self, IdError> {
                Uuid::try_parse(raw.trim())
                    .map_err(|_| IdError::Malformed)
                    .and_then(Self::from_uuid)
            }

            #[must_use]
            pub fn as_uuid(&self) -> Uuid {
                self.0
            }
        }

        impl fmt::Display for $name {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                self.0.hyphenated().fmt(f)
            }
        }
    };
}

uuid_v7_id!(
    /// Identifies an agent.
    AgentId
);
uuid_v7_id!(
    /// Identifies an audit event.
    AuditEventId
);

#[cfg(test)]
mod tests {
    use super::*;

    const V7: &str = "01920000-0000-7000-8000-000000000001";

    #[test]
    fn accepts_only_version_7() {
        let id = AgentId::parse(V7).expect("v7");

        assert_eq!(id.to_string(), V7);
        assert_eq!(AgentId::from_uuid(id.as_uuid()), Ok(id));
        assert_eq!(AgentId::parse(&format!(" {} ", V7.to_uppercase())), Ok(id));
        assert_eq!(
            AuditEventId::parse("67e55044-10b1-426f-9247-bb680e5fe0c8"),
            Err(IdError::NotV7)
        );
        assert_eq!(AgentId::parse("not-a-uuid"), Err(IdError::Malformed));
        assert_eq!(AgentId::from_uuid(Uuid::nil()), Err(IdError::NotV7));
    }
}
